/**
 * Jinx Balloonist + Marionette: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Balloonist
 * Wiki: https://wiki.bloodontheclocktower.com/Marionette
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { gainedSetupAbilities } from '#lib/core/rules/gained-abilities.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes.ts';
import { thinksPartnerSetup } from '#lib/core/rules/jinx-effects.ts';
import { marionetteAs, tableSetup } from './marionette.test-support.ts';

describe('Balloonist + Marionette jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'balloonist', 'marionette');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('balloonist')?.name).toBe('Balloonist');
		expect(data.byId.get('marionette')?.name).toBe('Marionette');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['balloonist', 'marionette'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['balloonist'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['marionette'])).not.toContain(jinx);
	});

	describe('a Marionette who thinks they are the Balloonist may have added an Outsider', () => {
		// Seat 0 the Marionette as the Balloonist, then the Imp, three Townsfolk and two
		// Outsiders: one more Outsider than the table allows without the Balloonist's change.
		const others = ['imp', 'chef', 'empath', 'monk', 'butler', 'saint'];
		const mismatch = (s: typeof base) =>
			tableSetup(s).warnings.filter(
				(w) => w.code === 'count-mismatch' && w.message.includes('Outsider')
			);
		const base = marionetteAs('balloonist', others);

		it("is data in the Marionette's rules", () => {
			// Wiki: "If the Marionette thinks that they are the Balloonist, an Outsider might have been added during setup."
			expect(ownJinxRules(base.game, 'marionette', 'balloonist', base.characters)).toEqual({
				thinksPartnerSetup: {}
			});
			expect(thinksPartnerSetup(base.game, base.seat(0), base.characters)).toBe('balloonist');
		});

		it("applies the Balloonist's setup change, so an extra Outsider fits", () => {
			// Wiki: "an Outsider might have been added during setup."
			expect(gainedSetupAbilities(base.game, base.characters).map((c) => c.id)).toEqual([
				'balloonist'
			]);
			expect(tableSetup(base).expected.outsider).toEqual([0, 1, 2]);
			expect(mismatch(base)).toEqual([]);
		});

		it('changes nothing with the Balloonist off the script', () => {
			// Wiki: "If the Marionette thinks that they are the Balloonist"
			const off = marionetteAs('balloonist', others, false);
			expect(gainedSetupAbilities(off.game, off.characters)).toEqual([]);
			expect(tableSetup(off).expected.outsider).toEqual([0, 1]);
			expect(mismatch(off)).not.toEqual([]);
		});
	});
});
